let books=M.create('books');let bookReport=M.ledgerReport(books);equal(bookReport.goldCost,182,'initial gold basis is two grams at 91 each');equal(bookReport.wealth,542,'initial cash and gold at cost');M.observe(books);const bookBuy=books.credits;check(M.trade(books,'buy',1),'ledger gold purchase');equal(M.ledgerReport(books).wealthChange,0,'gold purchase swaps cash for inventory');equal(M.ledgerReport(books).cashChange,books.credits-360,'purchase cash change exact');check(M.trade(books,'sell',1),'ledger gold sale');equal(M.ledgerReport(books).wealthChange,M.realised(books).total,'sale gain and wealth at cost agree');check(M.action(books,'meal'),'ledger meal');check(books.ledger.totals.food.out===7,'meal included in expenses');moor(books,'market');const bookProfile=Pr.create();check(Pr.apply(bookProfile,books,'hull','blue'),'ledger cosmetic purchase');equal(books.ledger.totals.cosmetics.out,12,'paint included');check(M.action(books,'hold'),'ledger upgrade');equal(books.ledger.totals.upgrades.out,65,'cargo racks included');books.fuel=3;moor(books,'landing');check(M.action(books,'fuel'),'ledger refuel');equal(books.ledger.totals.fuel.out,30,'whole refill charged');check(M.ledgerReport(books).reconciled,'all recorded cash reconciles');check(M.valid(books),'complete ledger save valid');check(!M.valid({...books,ledger:{...books.ledger,totals:{food:{in:0,out:-1}}}}),'negative ledger amount rejected');
