let fullRoute=M.create('combined');const routeBefore=JSON.stringify(fullRoute),route=M.combinedPlan(fullRoute,['bowls','seals']);check(route&&route.legs.length===4,'combined route has both collections and deliveries');for(const id of route.ids){check(route.legs.findIndex(l=>l.id===id&&l.kind==='collect')<route.legs.findIndex(l=>l.id===id&&l.kind==='deliver'),'collection precedes delivery');}equal(route.gross,30,'combined gross includes both purchases');equal(route.returnFuel,M.routeStats(fullRoute,W.ports.find(p=>p.id===route.legs.at(-1).quay),W.ports.find(p=>p.id==='bar')).fuel,'homeward fuel included, including routes ending at home');equal(JSON.stringify(fullRoute),routeBefore,'planning is read-only');check(M.saveBundle(fullRoute,['bowls','seals']),'combined route saved');equal(fullRoute.track,'bundle','combined route tracked');check(M.valid(fullRoute),'combined route reload valid');check(M.stories(fullRoute).some(r=>r.id==='bundle'&&!r.done),'combined objective shown');moor(fullRoute,'canal');M.freight(fullRoute,'bowls',false);check(M.combinedPlan(fullRoute,['bowls','seals']).legs.length===3,'held case skips second purchase');equal(M.combinedPlan(fullRoute,['bowls','seals']).alreadyPaid,20,'already paid basis shown');equal(M.combinedPlan(fullRoute,['bowls','seals']).gross,30,'held purchase still counts against gross profit');check(!M.combinedPlan(fullRoute,['bowls','bowls']),'duplicate order rejected');fullRoute.flags.teaAccepted=true;check(M.combinedPlan(fullRoute,['bowls','seals']).feasible,'deliver carried case first to make space');equal(M.combinedPlan(fullRoute,['bowls','seals']).legs[0].kind,'deliver','capacity chooses delivery before next pickup');fullRoute.flags.teaAccepted=false;fullRoute.clock=1770;check(!M.combinedPlan(fullRoute,['bowls','seals']).feasible,'late combined route marked infeasible');
