for(const menu of ['rice','soup']){const f=M.create('festival-'+menu);moor(f,'canal');check(!M.action(f,'festival-start'),'festival follows preview');f.flags.naoPreview=true;f.flags.naoAboard=true;check(M.action(f,'festival-start'),'Hana invitation');check(!M.action(f,'festival-supplies'),'cannot deliver uncollected basket');check(M.action(f,'festival-citrus'),'Jun citrus');equal(M.held(f),1,'citrus starts shared festival basket');moor(f,'bar');check(M.action(f,'festival-rice'),'Mei rice');equal(M.held(f),1,'two ingredients share one slot');check(!M.action(f,'festival-rice'),'supplies cannot be purchased twice');moor(f,'canal');check(M.action(f,'festival-supplies'),'basket placed');equal(M.held(f),0,'festival supplies release hold');check(!M.action(f,'festival-open'),'lanterns and menu needed');check(M.action(f,'festival-lights'),'Mako lantern preparation');check(M.action(f,'festival-menu-'+menu),'Nao menu choice');check(M.action(f,'festival-open'),'festival opens');check(!M.action(f,'festival-menu-'+(menu==='rice'?'soup':'rice')),'opened menu cannot change');check(!M.action(f,'festival-open'),'cannot reopen');check(M.action(f,'festival-tea'),'festival tea stall');check(M.action(f,'festival-bun'),'festival bun stall');check(M.action(f,'festival-celebrate'),'festival celebration');check(!M.action(f,'festival-celebrate'),'celebration once');equal(f.credits,339,'supplies and all purchases total 21; no invented sales');equal(f.ledger.totals.festival.out,21,'festival spending tracked');check(M.ledgerReport(f).reconciled,'festival ledger reconciles');check(M.stories(f).find(r=>r.id==='festival').done,'festival outcome kept');check(M.valid(JSON.parse(JSON.stringify(f))),'festival save valid');f.ended=true;const memories=Pr.create();check(Pr.record(memories,f),'festival remembered in profile');check(Pr.valid(memories),'memory and accounting profile valid');const again=M.create('next-festival');const memoryBefore=again.clock;check(Pr.recall(memories,again,'nao').includes('festival'),'Nao remembers earlier festival');equal(again.clock,memoryBefore,'memory reading takes no time');check(Pr.recall(memories,again,'nao')!=='','memory lookup remains safe');check(memories.letters.some(l=>l.who==='hana'),'Hana writes after festival');const tags=memories.memories.nao.length;Pr.record(memories,f);equal(memories.memories.nao.length,tags,'opening same report does not duplicate memories');check(!Pr.valid({...memories,memories:{nao:['unknown']}}),'unknown memory rejected');}
